/**
 * SecureAuthX — regression tests for features that must NOT change:
 * deterministic password generation, master verifier, reuse hashing, strength
 * analysis, the documented limitations, and the permission surface. The golden
 * values below were generated by the pristine Phase 3B lib/crypto.js (before the
 * finalization changes). Run with: node --test tests/phase3b-regression.test.js
 */
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { deriveSitePassword, computeMasterVerifier, verifyAgainstVerifier, reuseComparisonHash } from "../lib/crypto.js";
import { analyzeStrength } from "../lib/strength.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const read = (rel) => fs.readFileSync(path.join(__dirname, rel), "utf8");

const GOLDEN_DERIVATIONS = [
  {
    "master": "Golden-Master-Password-1!",
    "domain": "example.com",
    "account": "Default",
    "opts": {},
    "expected": "H3CGlb[^^4e{gR@3Vv{!"
  },
  {
    "master": "Golden-Master-Password-1!",
    "domain": "example.com",
    "account": "Work",
    "opts": {
      "length": 24
    },
    "expected": "MzpxpVZ)$Q1mr5ELfD-zpj=a"
  },
  {
    "master": "Golden-Master-Password-1!",
    "domain": "other.example",
    "account": "Default",
    "opts": {},
    "expected": "T{On%*I#ClHmGK48p6r!"
  },
  {
    "master": "E2ETestMasterPassword123!",
    "domain": "golden.example",
    "account": "Default",
    "opts": {},
    "expected": "TGuE=@6!($xI=1m$5HY2"
  }
];
const VERIFIER_SALT = "00112233445566778899aabbccddeeff";
const GOLDEN_VERIFIER = "d8e1be33add6ceaf54d132dd71965461f9890f261ec188a4fa1edce0993554b0";
const GOLDEN_REUSE_HASH = "7e726d9eaec0863c9189f069df928775409825db8e2532a4bc66056335e43622";

test("deterministic site passwords are byte-for-byte unchanged from the pristine baseline", async () => {
  for (const c of GOLDEN_DERIVATIONS) {
    assert.equal(await deriveSitePassword(c.master, c.domain, c.account, c.opts), c.expected, JSON.stringify([c.domain, c.account, c.opts]));
  }
});

test("deterministic generation: honors length, and domain/account/master all change the output", async () => {
  const a = await deriveSitePassword("m-1", "a.example", "Default");
  assert.equal(a, await deriveSitePassword("m-1", "a.example", "Default"));
  assert.notEqual(a, await deriveSitePassword("m-1", "b.example", "Default"));
  assert.notEqual(a, await deriveSitePassword("m-1", "a.example", "Other"));
  assert.notEqual(a, await deriveSitePassword("m-2", "a.example", "Default"));
  assert.equal((await deriveSitePassword("m-1", "a.example", "Default", { length: 30 })).length, 30);
});

test("master verifier is unchanged and still verifies correctly", async () => {
  assert.equal((await computeMasterVerifier("Golden-Master-Password-1!", VERIFIER_SALT)).verifierHex, GOLDEN_VERIFIER);
  assert.equal(await verifyAgainstVerifier("Golden-Master-Password-1!", VERIFIER_SALT, GOLDEN_VERIFIER), true);
  assert.equal(await verifyAgainstVerifier("wrong", VERIFIER_SALT, GOLDEN_VERIFIER), false);
});

test("reuse-detection hash is unchanged and distinguishes passwords", async () => {
  assert.equal(await reuseComparisonHash("Golden-Password-1"), GOLDEN_REUSE_HASH);
  assert.notEqual(await reuseComparisonHash("Golden-Password-2"), GOLDEN_REUSE_HASH);
});

test("strength analysis: empty, common, repetitive, and strong passwords", () => {
  const empty = analyzeStrength("");
  assert.equal(empty.score, 0);
  assert.equal(empty.label, "Empty");

  const common = analyzeStrength("password");
  assert.ok(common.score <= 10, "a common password must score very low");
  assert.ok(common.issues.some((i) => /common/i.test(i)));

  const repeated = analyzeStrength("aaaa1111");
  assert.ok(repeated.issues.some((i) => /repeated/i.test(i)));
  assert.ok(repeated.score < 60);

  const strong = analyzeStrength("H3CGlb[^^4e{gR@3Vv{!");
  assert.equal(strong.score, 100);
  assert.deepEqual(strong.issues, []);
});

test("docs/LIMITATIONS.md documents the hostname-vs-port limitation, the clipboard limitation, and the timeout test method", () => {
  const doc = read("../docs/LIMITATIONS.md");
  assert.match(doc, /hostname/i);
  assert.match(doc, /port/i);
  assert.match(doc, /different ports/i);
  assert.match(doc, /clipboard/i);
  assert.match(doc, /does not clear it later|not cleared automatically/i);
  assert.match(doc, /30[- ]minute/i);
});

test("the popup never overwrites or clears the clipboard (no empty writeText)", () => {
  const popup = read("../popup/popup.js");
  assert.ok(!/writeText\(\s*(""|'')\s*\)/.test(popup));
});

test("the vault popup UI states the clipboard limitation and the domain-only rule", () => {
  const html = read("../popup/popup.html");
  assert.match(html, /id="vaultClipboardNote"/);
  assert.match(html, /does not clear the clipboard automatically/i);
  assert.match(html, /domain only: no https:\/\/, port, or path/i);
});

test("manifest permissions are unchanged from the verified baseline (no new permission for the vault)", () => {
  const m = JSON.parse(read("../manifest.json"));
  assert.deepEqual(m.permissions, ["storage", "activeTab", "tabs", "cookies", "scripting", "webRequest", "alarms"]);
  assert.equal(m.externally_connectable, undefined);
});
